import fs from "node:fs";
import path from "node:path";

/**
 * Product story coverage audit.
 *
 * Governed product stories (src/wingman2/data/productStories.ts) are the
 * high-confidence sales copy a rep can quote directly. Everything else falls back
 * to auto-generated positioning that the UI flags "verify before quoting". This
 * audit measures coverage against the live 2026 catalogue, prints the gap, and
 * writes a prioritised backlog so the authoring work is tracked instead of hidden.
 *
 * Run: node tools/audit-product-story-coverage.mjs
 */

const repoRoot = process.cwd();
const storiesPath = path.join(repoRoot, "src", "wingman2", "data", "productStories.ts");
const catalogPath = path.join(repoRoot, "data", "catalog", "wyrestormSkuCatalog.2026.json");
const backlogPath = path.join(repoRoot, "docs", "product-story-coverage-backlog.md");

for (const file of [storiesPath, catalogPath]) {
  if (!fs.existsSync(file)) {
    console.error(`[story-coverage] Missing required file: ${path.relative(repoRoot, file)}`);
    process.exit(1);
  }
}

// Story SKUs: a top-level story entry is a `sku: "..."` immediately followed by
// `plainEnglishName:` (worksWith entries are followed by `reason:` instead).
const storiesText = fs.readFileSync(storiesPath, "utf8");
const storySkus = new Set(
  [...storiesText.matchAll(/\n\s*sku:\s*"([^"]+)",\s*\n\s*plainEnglishName:/g)].map((m) => m[1].toUpperCase()),
);

const catalog = JSON.parse(fs.readFileSync(catalogPath, "utf8"));
const catalogSkus = catalog.map((entry) => String(entry?.sku ?? "").toUpperCase()).filter(Boolean);

// Accessories that do not need a sales story (cables, mounts, spares, PSUs).
const ACCESSORY = /^(CAB|MOUNT|BRKT)\b|CABLE|MOUNT|BRACKET|\bPSU\b|POWER SUPPLY|SPARE/i;
const isAccessory = (sku) => ACCESSORY.test(sku);

const sellable = catalogSkus.filter((sku) => !isAccessory(sku));
const covered = sellable.filter((sku) => storySkus.has(sku));
const uncovered = sellable.filter((sku) => !storySkus.has(sku));

const pct = sellable.length ? Math.round((covered.length / sellable.length) * 100) : 0;

// Group uncovered SKUs by family prefix so authoring can be batched by range.
const byFamily = new Map();
for (const sku of uncovered) {
  const family = sku.split("-")[0].replace(/\s+\d+$/, "").split(" ")[0];
  if (!byFamily.has(family)) byFamily.set(family, []);
  byFamily.get(family).push(sku);
}
const families = [...byFamily.entries()].sort((a, b) => b[1].length - a[1].length);

console.log(`[story-coverage] Governed stories: ${storySkus.size}`);
console.log(`[story-coverage] Sellable catalogue SKUs (accessories excluded): ${sellable.length}`);
console.log(`[story-coverage] Covered: ${covered.length} (${pct}%)  |  Uncovered: ${uncovered.length}`);
console.log(`[story-coverage] Top uncovered families:`);
for (const [family, skus] of families.slice(0, 12)) {
  console.log(`  ${family.padEnd(8)} ${skus.length}`);
}

const lines = [];
lines.push("# Product story coverage backlog");
lines.push("");
lines.push("> Generated by `node tools/audit-product-story-coverage.mjs`. Do not edit by hand.");
lines.push("");
lines.push(`- Governed stories: **${storySkus.size}**`);
lines.push(`- Sellable catalogue SKUs (accessories excluded): **${sellable.length}**`);
lines.push(`- Covered: **${covered.length} (${pct}%)** · Uncovered: **${uncovered.length}**`);
lines.push("");
lines.push("Uncovered SKUs fall back to auto-generated positioning that the app flags");
lines.push('"verify before quoting". Author governed stories family-by-family, highest count first.');
lines.push("");
lines.push("## Uncovered, grouped by family");
lines.push("");
for (const [family, skus] of families) {
  lines.push(`### ${family} (${skus.length})`);
  lines.push("");
  lines.push(skus.sort().map((sku) => `- [ ] ${sku}`).join("\n"));
  lines.push("");
}

fs.mkdirSync(path.dirname(backlogPath), { recursive: true });
fs.writeFileSync(backlogPath, lines.join("\n"));
console.log(`[story-coverage] Backlog written to ${path.relative(repoRoot, backlogPath)}`);
